//! Error-code registry (D-7): stable `LIG-E###` codes generated from
//! `docs/errors/*.md`, Svelte's catalog machinery (§2.3).

// @generated by `lig errors-gen` from docs/errors/*.md — do not edit.
mod generated;

/// One diagnostic code in the registry.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ErrorCode {
    /// Stable code, e.g. `LIG-E114`.
    pub code: &'static str,
    /// Short title from the catalog.
    pub title: &'static str,
    /// `true` while the owning milestone has not shipped the rule.
    pub reserved: bool,
    /// Owning milestone, e.g. `"M1"`; `"active"` codes report `"M0"`.
    pub stage: &'static str,
}

/// Look up a code in the registry.
#[must_use]
pub fn lookup(code: &str) -> Option<&'static ErrorCode> {
    generated::REGISTRY.iter().find(|e| e.code == code)
}

/// The full registry, ordered by code.
#[must_use]
pub const fn registry() -> &'static [ErrorCode] {
    generated::REGISTRY
}

/// The canonical per-code documentation URL (§12.2).
#[must_use]
pub fn url(code: &str) -> String {
    format!("https://ligature.dev/e/{code}")
}

#[cfg(test)]
mod tests {
    use super::{lookup, registry, url};

    #[test]
    fn codes_are_unique_and_well_formed() {
        let mut seen = std::collections::BTreeSet::new();
        for e in registry() {
            assert!(
                e.code.starts_with("LIG-E") || e.code.starts_with("LIG-W"),
                "bad code {}",
                e.code
            );
            assert_eq!(e.code.len(), 8, "code {} must be LIG-?###", e.code);
            assert!(!e.title.is_empty(), "{} needs a title", e.code);
            assert!(seen.insert(e.code), "duplicate code {}", e.code);
        }
    }

    #[test]
    fn known_codes_resolve() {
        assert!(lookup("LIG-E001").is_some());
        assert!(lookup("LIG-E114").is_some());
        assert!(lookup("LIG-E401").is_some());
        assert!(lookup("LIG-E999").is_none());
        assert_eq!(
            lookup("LIG-E114").unwrap().title.to_lowercase(),
            "function call with callback not admitted in view expressions"
        );
    }

    #[test]
    fn urls_follow_the_catalog_scheme() {
        assert_eq!(url("LIG-E114"), "https://ligature.dev/e/LIG-E114");
    }

    #[test]
    fn catalog_docs_are_in_sync() {
        // The generated registry must match docs/errors/*.md exactly.
        let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/../../docs/errors");
        let mut codes = std::collections::BTreeSet::new();
        for entry in std::fs::read_dir(dir).expect("docs/errors exists") {
            let path = entry.unwrap().path();
            if path.extension().is_some_and(|ext| ext == "md") {
                let name = path.file_stem().unwrap().to_string_lossy().to_string();
                codes.insert(name);
            }
        }
        let registered: std::collections::BTreeSet<_> =
            registry().iter().map(|e| e.code.to_string()).collect();
        assert_eq!(codes, registered, "docs/errors and registry disagree");
    }
}
